func expandCodexBuiltinReview(skills []string) []string {
	out := make([]string, 0, len(skills))
	for _, skill := range skills {
		if skill == "/review" {
			out = append(out, codexBuiltinReviewPrompt)
			continue
		}
		out = append(out, skill)
